import type { AuthoredCatalogRecord, AuthoredLocale, AuthoredProducerLocale, AuthoredWineLocale } from './authoredCatalogTypes'
import type { WineStyle } from '../types'

const four = <T>(en: T, de: T, fr: T, es: T): Record<AuthoredLocale, T> => ({ en, de, fr, es })
type ProducerFieldCopy = Partial<Pick<AuthoredProducerLocale, 'summary'|'philosophy'|'vineyard'|'cellar'|'speciality'>>
const producerCopy: Record<string, Record<AuthoredLocale, ProducerFieldCopy>> = {}
const producer = (id: string, regionId: string, sourceUrls: string[], locales: Record<AuthoredLocale, AuthoredProducerLocale>): AuthoredCatalogRecord => {
  const copy = producerCopy[id]
  const resolved = copy ? {
    en: { ...locales.en, ...copy.en },
    de: { ...locales.de, ...copy.de },
    fr: { ...locales.fr, ...copy.fr },
    es: { ...locales.es, ...copy.es },
  } : locales
  return { recordType: 'producer', id, regionId, sourceUrls, locales: resolved }
}
const wine = (id: string, producerId: string, regionId: string, grapeIds: string[], style: WineStyle, vintage: number | null, sourceUrls: string[], locales: Record<AuthoredLocale, AuthoredWineLocale>): AuthoredCatalogRecord => ({ recordType: 'wine', id, producerId, regionId, grapeIds, style, vintage, sourceUrls, locales })

type WineSeed = { name: string; summary: Record<AuthoredLocale, string>; composition: string; vinification: string; maturation: string; window: string; serving?: string; pairs: Record<AuthoredLocale, string[]> }
type WineFieldCopy = Partial<Pick<AuthoredWineLocale, 'composition'|'vinification'|'maturation'|'drinkWindow'|'serving'>>
const f4 = (en: WineFieldCopy, de: WineFieldCopy, fr: WineFieldCopy, es: WineFieldCopy): Record<AuthoredLocale, WineFieldCopy> => ({ en, de, fr, es })
